// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _minSum, uint256 _am, address _sender) public {
        // Bound inputs
        _lockTime = bound(_lockTime, 0, 1e6);
        _minSum = bound(_minSum, 0, 1e18);
        _am = bound(_am, 0, 1e18);
        vm.assume(_sender != address(0));
        // Initialize contract and set MinSum
        c.SetMinSum(_minSum);
        c.Initialized();
        // Make a call to Collect via a user who may have some balance
        vm.deal(_sender, 1e18);
        vm.prank(_sender);
        (bool success, ) = address(c).call{value: 0}(""); // fallback calls Put(0)
        // Now call Collect(uint256) – may revert
        vm.prank(_sender);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        // The rule: MinSum equals the value set by SetMinSum before initialization
        assertTrue(c.MinSum() == _minSum);
    }
}

